```python
import random

class Device:
    def __init__(self, id):
        self.id = id
        self.infected = False

    def infect(self):
        self.infected = True

    def __str__(self):
        return f"Device {self.id}: {'Infected' if self.infected else 'Not Infected'}"


class MalwareSimulation:
    def __init__(self, num_devices, infection_rate):
        self.devices = [Device(i) for i in range(num_devices)]
        self.infection_rate = infection_rate

    def spread_malware(self):
        for device in self.devices:
            if device.infected:
                for _ in range(self.infection_rate):
                    target = random.choice(self.devices)
                    if not target.infected:
                        target.infect()

    def print_status(self):
        for device in self.devices:
            print(device)


if __name__ == "__main__":
    num_devices = 100
    infection_rate = 2

    simulation = MalwareSimulation(num_devices, infection_rate)

    # Infect one device to start the simulation
    simulation.devices[0].infect()

    print("Initial status:")
    simulation.print_status()

    # Spread the malware
    for _ in range(10):
        simulation.spread_malware()
        print("\nStatus after spreading malware:")
        simulation.print_status()
